-- Copia del esquema PROVISIONAL usado en el entorno de prueba prubasmoda.
-- SOLO ENTORNO DE DESARROLLO. No corresponde a producción.
begin;
create table if not exists public.categorias (id_categoria bigint generated by default as identity primary key, nombre_categoria text not null unique, estado text not null default 'ACTIVO');
create table if not exists public.tallas (id_talla bigint generated by default as identity primary key, nombre_talla text not null unique, estado text not null default 'ACTIVO');
create table if not exists public.colores (id_color bigint generated by default as identity primary key, nombre_color text not null unique, estado text not null default 'ACTIVO');
create table if not exists public.proveedores (id_proveedor bigint generated by default as identity primary key, nombre_proveedor text not null, estado text not null default 'ACTIVO');
create table if not exists public.clientes (id_cliente bigint generated by default as identity primary key, nombres text not null, apellidos text not null default '', correo text unique, estado text not null default 'ACTIVO', saldo_favor numeric(14,2) not null default 0);
create table if not exists public.roles (id_rol bigint generated by default as identity primary key, nombre_rol text not null unique, descripcion text, estado text not null default 'ACTIVO');
create table if not exists public.usuarios (id_usuario bigint generated by default as identity primary key, auth_user_id uuid unique references auth.users(id), correo text, estado text not null default 'ACTIVO');
create table if not exists public.usuarios_roles (id_usuario bigint not null references public.usuarios, id_rol bigint not null references public.roles, primary key(id_usuario,id_rol));
create table if not exists public.modulos (id_modulo bigint generated by default as identity primary key, codigo text not null unique);
create table if not exists public.permisos (id_permiso bigint generated by default as identity primary key, codigo text not null unique);
create table if not exists public.roles_permisos (id_rol bigint not null references public.roles, id_modulo bigint not null references public.modulos, id_permiso bigint not null references public.permisos, primary key(id_rol,id_modulo,id_permiso));
create table if not exists public.productos (id_producto bigint generated by default as identity primary key, referencia text unique, nombre_producto text not null, descripcion text, id_categoria bigint references public.categorias, genero text, estado text not null default 'ACTIVO');
create table if not exists public.variantes_producto (id_variante bigint generated by default as identity primary key, id_producto bigint not null references public.productos, id_talla bigint references public.tallas, id_color bigint references public.colores, precio_venta numeric(14,2) not null default 0 check(precio_venta>=0), stock_actual integer not null default 0 check(stock_actual>=0), stock_minimo integer not null default 0, stock_maximo integer not null default 0, estado text not null default 'ACTIVO');
create table if not exists public.compras (id_compra bigint generated by default as identity primary key, id_proveedor bigint references public.proveedores, fecha_compra date not null default current_date, fecha_registro date not null default current_date, numero_factura_proveedor text, iva numeric(14,2) not null default 0, tipo_pago text not null default 'CONTADO', estado text not null default 'ACTIVA');
create table if not exists public.detalles_compra (id_detalle_compra bigint generated by default as identity primary key, id_compra bigint not null references public.compras, id_variante bigint not null references public.variantes_producto, cantidad integer not null check(cantidad>0), costo_unitario numeric(14,2) not null check(costo_unitario>=0), precio_venta numeric(14,2));
create table if not exists public.ventas (id_venta bigint generated by default as identity primary key, id_cliente bigint references public.clientes, fecha_venta date not null default current_date, metodo_pago text, subtotal numeric(14,2) not null default 0, descuento numeric(14,2) not null default 0, total_venta numeric(14,2) not null default 0, saldo_aplicado numeric(14,2) not null default 0, estado text not null default 'PENDIENTE', origen text not null default 'ADMIN', comprobante_url text, comprobante_nombre text, motivo_rechazo text);
create table if not exists public.detalles_venta (id_detalle_venta bigint generated by default as identity primary key, id_venta bigint not null references public.ventas, id_variante bigint not null references public.variantes_producto, cantidad integer not null check(cantidad>0), precio_unitario numeric(14,2) not null, subtotal numeric(14,2) not null);
create table if not exists public.planes_separe (id_plan_separe bigint generated by default as identity primary key, id_cliente bigint references public.clientes, fecha_inicio date not null default current_date, fecha_vencimiento date, estado text not null default 'ACTIVO', abono_inicial numeric(14,2) not null default 0, metodo_abono_inicial text);
create table if not exists public.detalles_plan_separe (id_detalle bigint generated by default as identity primary key, id_plan_separe bigint not null references public.planes_separe, id_variante bigint not null references public.variantes_producto, cantidad integer not null check(cantidad>0), precio_unitario numeric(14,2) not null);
create table if not exists public.abonos_separe (id_abono bigint generated by default as identity primary key, id_plan_separe bigint not null references public.planes_separe, fecha_abono date not null default current_date, valor_abono numeric(14,2) not null check(valor_abono>0), metodo_pago text, observacion text, estado text not null default 'ACTIVO');
create table if not exists public.devoluciones (id_devolucion bigint generated by default as identity primary key, id_venta bigint references public.ventas, id_cliente bigint references public.clientes, fecha_devolucion date not null default current_date, motivo text not null, descripcion text, tipo_respuesta text, estado text not null default 'PENDIENTE');
create table if not exists public.detalles_devolucion (id_detalle bigint generated by default as identity primary key, id_devolucion bigint not null references public.devoluciones, id_variante bigint references public.variantes_producto, cantidad integer not null check(cantidad>0), motivo text, descripcion text);
create table if not exists public.perdidas (id_perdida bigint generated by default as identity primary key, id_devolucion bigint references public.devoluciones, id_variante bigint references public.variantes_producto, cantidad integer not null check(cantidad>0), motivo text, descripcion text, estado text not null default 'ACTIVA');
do $$ declare t text; begin foreach t in array array['categorias','tallas','colores','proveedores','clientes','roles','usuarios','usuarios_roles','modulos','permisos','roles_permisos','productos','variantes_producto','compras','detalles_compra','ventas','detalles_venta','planes_separe','detalles_plan_separe','abonos_separe','devoluciones','detalles_devolucion','perdidas'] loop execute format('alter table public.%I enable row level security', t); end loop; end $$;
commit;
